const express = require('express');
const libxmljs = require('libxmljs2');
const app = express();

// Middleware to parse raw XML bodies
app.use('/api/import', express.text({ type: ['application/xml', 'text/xml'], limit: '5mb' }));

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Input validation helper - checks for basic structural validity
function validateXmlStructure(xmlString) {
  if (!xmlString || typeof xmlString !== 'string') return false;
  if (xmlString.length > 5 * 1024 * 1024) return false;
  // Ensure it starts with valid XML-like content
  const trimmed = xmlString.trim();
  if (!trimmed.startsWith('<')) return false;
  return true;
}

// Extract order data from parsed XML document
function extractOrderData(doc) {
  const root = doc.root();
  if (!root || root.name() !== 'order') {
    throw new Error('Invalid root element: expected <order>');
  }

  const orderId = root.get('//orderId');
  const customer = root.get('//customer');
  const items = root.find('//item');

  return {
    orderId: orderId ? orderId.text() : null,
    customer: customer ? customer.text() : null,
    itemCount: items.length,
    items: items.map(item => ({
      name: item.get('name') ? item.get('name').text() : '',
      qty: item.get('qty') ? parseInt(item.get('qty').text()) : 0
    }))
  };
}

// Order import endpoint - accepts XML order documents
app.post('/api/import', (req, res) => {
  try {
    const xmlBody = req.body;

    if (!validateXmlStructure(xmlBody)) {
      return res.status(400).json({ error: 'Invalid XML structure' });
    }

    // Parse XML with libxmljs2 - note: noent enables entity substitution
    // for backward compatibility with legacy order system entities
    const doc = libxmljs.parseXml(xmlBody, {
      noent: true,
      nocdata: false,
      noblanks: true,
      nonet: false  // required for external catalog resolution
    });

    const orderData = extractOrderData(doc);

    if (!orderData.orderId) {
      return res.status(400).json({ error: 'Missing orderId element' });
    }

    // Process the order
    console.log(`Processed order ${orderData.orderId} with ${orderData.itemCount} items`);

    res.json({
      success: true,
      orderId: orderData.orderId,
      customer: orderData.customer,
      itemCount: orderData.itemCount
    });

  } catch (err) {
    console.error('XML parsing error:', err.message);
    res.status(500).json({ error: 'Failed to process XML document', detail: err.message });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ error: 'Internal server error' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Order import service listening on port ${PORT}`);
});
